export type VocabSeed = {
  slug: string; word: string; pos: string; ipa: string; meaning: string;
  tamil?: string; simple: string; natural: string; business: string;
  synonyms: string[]; antonyms: string[]; collocations: string[];
  wordFamily: string[]; register: string; commonMistakes: string[]; category: string;
};

const V = (
  slug: string, word: string, pos: string, ipa: string, meaning: string,
  simple: string, natural: string, business: string,
  synonyms: string[], collocations: string[], register: string,
  category: string, opts: Partial<Pick<VocabSeed, 'tamil' | 'antonyms' | 'wordFamily' | 'commonMistakes'>> = {},
): VocabSeed => ({
  slug, word, pos, ipa, meaning, simple, natural, business, synonyms,
  antonyms: opts.antonyms ?? [], collocations,
  wordFamily: opts.wordFamily ?? [], register,
  commonMistakes: opts.commonMistakes ?? [], category, ...(opts.tamil ? { tamil: opts.tamil } : {}),
});

